	// Test case 1: quantity < 10 (no discount)
	total++
	if runTest("quantity 9, no discount applied", 10.0, 9, 90.0) {
		passed++
	}

	// Test case 2: quantity >= 10 and < 50 (10% discount) - boundary
	total++
	if runTest("quantity 10, 10%% discount applied", 10.0, 10, 90.0) {
