        expected: 90
    },
    {
        description: "Boundary: Quantity exactly 10 (10% discount)",
        price: 10,
        quantity: 10,
        expected: 90
    },
    {
        description: "Quantity less than 50 (10% discount)",
        price: 10,
        quantity: 49,
        expected: 441
    },
