        description: "Boundary: Quantity exactly 50 (25% discount)",
        price: 10,
        quantity: 50,
        expected: 375
    },
    {
        description: "Quantity greater than 50 (25% discount)",
        price: 20,
        quantity: 100,
        expected: 1500
    }
];

