var result = words
    .GroupBy(w => w)
    .Select(g => new { Word = g.Key, Count = g.Count() })
    .OrderByDescending(x => x.Count)
    .ThenBy(x => x.Word);

// Output results
foreach (var item in result)
{
    Console.WriteLine($"{item.Word}: {item.Count}");
